  1→#[cfg(target_os = "macos")]
  2→use core::ptr;
  3→use core::{fmt::Display, mem, str};
  4→use std::env;
  5→use std::fs;
  6→use std::io::{self, BufRead, BufReader};
  7→use std::os::fd::{AsRawFd, RawFd};
  8→
  9→#[cfg(not(target_os = "macos"))]
 10→use once_cell::sync::Lazy;
 11→
 12→use crate::kb::Key;
 13→use crate::term::Term;
 14→
 15→pub(crate) use crate::common_term::*;
 16→
 17→pub(crate) const DEFAULT_WIDTH: u16 = 80;
 18→
 19→#[inline]
 20→pub(crate) fn is_a_terminal(out: &impl AsRawFd) -> bool {
 21→    unsafe { libc::isatty(out.as_raw_fd()) != 0 }
 22→}
 23→
 24→pub(crate) fn is_a_color_terminal(out: &Term) -> bool {
 25→    if !is_a_terminal(out) {
 26→        return false;
 27→    }
 28→
 29→    if env::var("NO_COLOR").is_ok() {
 30→        return false;
 31→    }
 32→
 33→    match env::var("TERM") {
 34→        Ok(term) => term != "dumb",
 35→        Err(_) => false,
 36→    }
 37→}
 38→
 39→pub(crate) fn is_a_true_color_terminal(out: &Term) -> bool {
 40→    if !is_a_color_terminal(out) {
 41→        return false;
 42→    }
 43→    env::var("COLORTERM").is_ok_and(|term| term == "truecolor" || term == "24bit")
 44→}
 45→
 46→fn c_result<F: FnOnce() -> libc::c_int>(f: F) -> io::Result<()> {
 47→    let res = f();
 48→    if res != 0 {
 49→        Err(io::Error::last_os_error())
 50→    } else {
 51→        Ok(())
 52→    }
 53→}
 54→
 55→pub(crate) fn terminal_size(out: &Term) -> Option<(u16, u16)> {
 56→    if !is_a_terminal(out) {
 57→        return None;
 58→    }
 59→    let winsize = unsafe {
 60→        let mut winsize: libc::winsize = mem::zeroed();
 61→
 62→        // FIXME: ".into()" used as a temporary fix for a libc bug
 63→        // https://github.com/rust-lang/libc/pull/704
 64→        #[allow(clippy::useless_conversion)]
 65→        libc::ioctl(out.as_raw_fd(), libc::TIOCGWINSZ.into(), &mut winsize);
 66→        winsize
 67→    };
 68→    if winsize.ws_row > 0 && winsize.ws_col > 0 {
 69→        Some((winsize.ws_row, winsize.ws_col))
 70→    } else {
 71→        None
 72→    }
 73→}
 74→
 75→enum Input<T> {
 76→    Stdin(io::Stdin),
 77→    File(T),
 78→}
 79→
 80→impl Input<BufReader<fs::File>> {
 81→    fn buffered() -> io::Result<Self> {
 82→        Ok(match Input::unbuffered()? {
 83→            Input::Stdin(s) => Input::Stdin(s),
 84→            Input::File(f) => Input::File(BufReader::new(f)),
 85→        })
 86→    }
 87→}
 88→
 89→impl Input<fs::File> {
 90→    fn unbuffered() -> io::Result<Self> {
 91→        let stdin = io::stdin();
 92→        if is_a_terminal(&stdin) {
 93→            Ok(Input::Stdin(stdin))
 94→        } else {
 95→            let f = fs::OpenOptions::new()
 96→                .read(true)
 97→                .write(true)
 98→                .open("/dev/tty")?;
 99→            Ok(Input::File(f))
100→        }
101→    }
102→}
103→
104→// NB: this is not a full BufRead implementation because io::Stdin does not implement BufRead.
105→impl<T: BufRead> Input<T> {
106→    fn read_line(&mut self, buf: &mut String) -> io::Result<usize> {
107→        match self {
108→            Self::Stdin(s) => s.read_line(buf),
109→            Self::File(f) => f.read_line(buf),
110→        }
111→    }
112→}
113→
114→impl AsRawFd for Input<fs::File> {
115→    fn as_raw_fd(&self) -> RawFd {
116→        match self {
117→            Self::Stdin(s) => s.as_raw_fd(),
118→            Self::File(f) => f.as_raw_fd(),
119→        }
120→    }
121→}
122→
123→impl AsRawFd for Input<BufReader<fs::File>> {
124→    fn as_raw_fd(&self) -> RawFd {
125→        match self {
126→            Self::Stdin(s) => s.as_raw_fd(),
127→            Self::File(f) => f.get_ref().as_raw_fd(),
128→        }
129→    }
130→}
131→
132→pub(crate) fn read_secure() -> io::Result<String> {
133→    let mut input = Input::buffered()?;
134→
135→    let mut termios = mem::MaybeUninit::uninit();
136→    c_result(|| unsafe { libc::tcgetattr(input.as_raw_fd(), termios.as_mut_ptr()) })?;
137→    let mut termios = unsafe { termios.assume_init() };
138→    let original = termios;
139→    termios.c_lflag &= !libc::ECHO;
140→    c_result(|| unsafe { libc::tcsetattr(input.as_raw_fd(), libc::TCSAFLUSH, &termios) })?;
141→    let mut rv = String::new();
142→
143→    let read_rv = input.read_line(&mut rv);
144→
145→    c_result(|| unsafe { libc::tcsetattr(input.as_raw_fd(), libc::TCSAFLUSH, &original) })?;
146→
147→    read_rv.map(|_| {
148→        let len = rv.trim_end_matches(&['\r', '\n'][..]).len();
149→        rv.truncate(len);
150→        rv
151→    })
152→}
153→
154→fn poll_fd(fd: RawFd, timeout: i32) -> io::Result<bool> {
155→    let mut pollfd = libc::pollfd {
156→        fd,
157→        events: libc::POLLIN,
158→        revents: 0,
159→    };
160→    let ret = unsafe { libc::poll(&mut pollfd as *mut _, 1, timeout) };
161→    if ret < 0 {
162→        Err(io::Error::last_os_error())
163→    } else {
164→        Ok(pollfd.revents & libc::POLLIN != 0)
165→    }
166→}
167→
168→#[cfg(target_os = "macos")]
169→fn select_fd(fd: RawFd, timeout: i32) -> io::Result<bool> {
170→    unsafe {
171→        let mut read_fd_set: libc::fd_set = mem::zeroed();
172→
173→        let mut timeout_val;
174→        let timeout = if timeout < 0 {
175→            ptr::null_mut()
176→        } else {
177→            timeout_val = libc::timeval {
178→                tv_sec: (timeout / 1000) as _,
179→                tv_usec: (timeout * 1000) as _,
180→            };
181→            &mut timeout_val
182→        };
183→
184→        libc::FD_ZERO(&mut read_fd_set);
185→        libc::FD_SET(fd, &mut read_fd_set);
186→        let ret = libc::select(
187→            fd + 1,
188→            &mut read_fd_set,
189→            ptr::null_mut(),
190→            ptr::null_mut(),
191→            timeout,
192→        );
193→        if ret < 0 {
194→            Err(io::Error::last_os_error())
195→        } else {
196→            Ok(libc::FD_ISSET(fd, &read_fd_set))
197→        }
198→    }
199→}
200→
201→fn select_or_poll_term_fd(fd: RawFd, timeout: i32) -> io::Result<bool> {
202→    // There is a bug on macos that ttys cannot be polled, only select()
203→    // works.  However given how problematic select is in general, we
204→    // normally want to use poll there too.
205→    #[cfg(target_os = "macos")]
206→    {
207→        if unsafe { libc::isatty(fd) == 1 } {
208→            return select_fd(fd, timeout);
209→        }
210→    }
211→    poll_fd(fd, timeout)
212→}
213→
214→fn read_single_char(fd: RawFd) -> io::Result<Option<char>> {
215→    // timeout of zero means that it will not block
216→    let is_ready = select_or_poll_term_fd(fd, 0)?;
217→
218→    if is_ready {
219→        // if there is something to be read, take 1 byte from it
220→        let mut buf: [u8; 1] = [0];
221→
222→        read_bytes(fd, &mut buf, 1)?;
223→        Ok(Some(buf[0] as char))
224→    } else {
225→        //there is nothing to be read
226→        Ok(None)
227→    }
228→}
229→
230→// Similar to libc::read. Read count bytes into slice buf from descriptor fd.
231→// If successful, return the number of bytes read.
232→// Will return an error if nothing was read, i.e when called at end of file.
233→fn read_bytes(fd: RawFd, buf: &mut [u8], count: u8) -> io::Result<u8> {
234→    let read = unsafe { libc::read(fd, buf.as_mut_ptr() as *mut _, count as usize) };
235→    if read < 0 {
236→        Err(io::Error::last_os_error())
237→    } else if read == 0 {
238→        Err(io::Error::new(
239→            io::ErrorKind::UnexpectedEof,
240→            "Reached end of file",
241→        ))
242→    } else if buf[0] == b'\x03' {
243→        Err(io::Error::new(
244→            io::ErrorKind::Interrupted,
245→            "read interrupted",
246→        ))
247→    } else {
248→        Ok(read as u8)
249→    }
